{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.7.12","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"gpu","dataSources":[{"sourceId":256618,"sourceType":"datasetVersion","datasetId":107620},{"sourceId":639622,"sourceType":"datasetVersion","datasetId":316368},{"sourceId":653195,"sourceType":"datasetVersion","datasetId":325566},{"sourceId":671851,"sourceType":"datasetVersion","datasetId":338555},{"sourceId":6060815,"sourceType":"datasetVersion","datasetId":3468263}],"isInternetEnabled":false,"language":"python","sourceType":"script","isGpuEnabled":true}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:12:17.818677Z\",\"iopub.execute_input\":\"2023-07-01T14:12:17.819071Z\",\"iopub.status.idle\":\"2023-07-01T14:12:22.087239Z\",\"shell.execute_reply.started\":\"2023-07-01T14:12:17.819039Z\",\"shell.execute_reply\":\"2023-07-01T14:12:22.085823Z\"}}\n\n#IMPORT THE LIBRARIES\nimport pandas as pd\nimport numpy as np\n\nimport os\nimport sys\n\n# librosa is a Python library for analyzing audio and music. It can be used to extract the data from the audio files we will see it later.\nimport librosa\nimport librosa.display\nimport seaborn as sns\nimport matplotlib.pyplot as plt\n\nfrom sklearn.preprocessing import StandardScaler, OneHotEncoder\nfrom sklearn.metrics import confusion_matrix, classification_report\nfrom sklearn.model_selection import train_test_split\n\n# to play the audio files\nimport IPython.display as ipd\nfrom IPython.display import Audio\nimport keras\nfrom keras.preprocessing import sequence\nfrom keras.models import Sequential\nfrom keras.layers import Dense, Embedding\nfrom keras.layers import LSTM,BatchNormalization , GRU\nfrom keras.preprocessing.text import Tokenizer\nfrom keras.preprocessing.sequence import pad_sequences\nfrom tensorflow.keras.utils import to_categorical\nfrom keras.layers import Input, Flatten, Dropout, Activation\nfrom keras.layers import Conv1D, MaxPooling1D, AveragePooling1D\nfrom keras.models import Model\nfrom keras.callbacks import ModelCheckpoint\nfrom tensorflow.keras.optimizers import SGD\n\n\n\nimport warnings\nif not sys.warnoptions:\n    warnings.simplefilter(\"ignore\")\nwarnings.filterwarnings(\"ignore\", category=DeprecationWarning) \nimport tensorflow as tf \nprint (\"Done\")\n\n# %% [code]\n!dpkg -s libsndfile1\n\n# %% [markdown]\n# # Importing Data \n\n# %% [code]\n#preparing data set\n\nravdess = \"/kaggle/input/ravdess-emotional-speech-audio/audio_speech_actors_01-24/\"\nravdess_directory_list = os.listdir(ravdess)\nprint(ravdess_directory_list)\n\n# %% [code]\nCrema = \"/kaggle/input/cremad/AudioWAV/\"\nTess = \"/kaggle/input/toronto-emotional-speech-set-tess/tess toronto emotional speech set data/TESS Toronto emotional speech set data/\"\nSavee = \"/kaggle/input/surrey-audiovisual-expressed-emotion-savee/ALL/\"\n\n# %% [markdown]\n# # Pre-processing\n\n# %% [code]\nfile_emotion = []\nfile_path = []\nfor i in ravdess_directory_list:\n    # as their are 24 different actors in our previous directory we need to extract files for each actor.\n    actor = os.listdir(ravdess + i)\n    for f in actor:\n        part = f.split('.')[0].split('-')\n    # third part in each file represents the emotion associated to that file.\n        file_emotion.append(int(part[2]))\n        file_path.append(ravdess + i + '/' + f)\n    \n\n# %% [code]\nprint(actor[0])\nprint(part[0])\nprint(file_path[0])\nprint(int(part[2]))\nprint(f)\n\n# %% [code]\n# dataframe for emotion of files\nemotion_df = pd.DataFrame(file_emotion, columns=['Emotions'])\n# dataframe for path of files.\npath_df = pd.DataFrame(file_path, columns=['Path'])\nravdess_df = pd.concat([emotion_df, path_df], axis=1)\n# changing integers to actual emotions.\nravdess_df.Emotions.replace({1:'neutral', 2:'neutral', 3:'happy', 4:'sad', 5:'angry', 6:'fear', 7:'disgust',\n                             8:'surprise'},\n                            inplace=True)\nprint(ravdess_df.head())\nprint(\"______________________________________________\")\nprint(ravdess_df.tail())\nprint(\"_______________________________________________\")\nprint(ravdess_df.Emotions.value_counts())\n\n\n\n# %% [code]\n#Tess Dataset\n\n# %% [code]\ntess_directory_list = os.listdir(Tess)\n\nfile_emotion = []\nfile_path = []\n\nfor dir in tess_directory_list:\n    directories = os.listdir(Tess + dir)\n    for file in directories:\n        part = file.split('.')[0]\n        part = part.split('_')[2]\n        if part=='ps':\n            file_emotion.append('surprise')\n        else:\n            file_emotion.append(part)\n        file_path.append(Tess + dir + '/' + file)\n        \n# dataframe for emotion of files\nemotion_df = pd.DataFrame(file_emotion, columns=['Emotions'])\n\n# dataframe for path of files.\npath_df = pd.DataFrame(file_path, columns=['Path'])\nTess_df = pd.concat([emotion_df, path_df], axis=1)\nTess_df.head()\nprint(Tess_df.Emotions.value_counts())\n\n\n# %% [code]\n#Crema Dataset\n\n# %% [code]\ncrema_directory_list = os.listdir(Crema)\n\nfile_emotion = []\nfile_path = []\n\nfor file in crema_directory_list:\n    # storing file paths\n    file_path.append(Crema + file)\n    # storing file emotions\n    part=file.split('_')\n    if part[2] == 'SAD':\n        file_emotion.append('sad')\n    elif part[2] == 'ANG':\n        file_emotion.append('angry')\n    elif part[2] == 'DIS':\n        file_emotion.append('disgust')\n    elif part[2] == 'FEA':\n        file_emotion.append('fear')\n    elif part[2] == 'HAP':\n        file_emotion.append('happy')\n    elif part[2] == 'NEU':\n        file_emotion.append('neutral')\n    else:\n        file_emotion.append('Unknown')\n        \n# dataframe for emotion of files\nemotion_df = pd.DataFrame(file_emotion, columns=['Emotions'])\n\n# dataframe for path of files.\npath_df = pd.DataFrame(file_path, columns=['Path'])\nCrema_df = pd.concat([emotion_df, path_df], axis=1)\nCrema_df.head()\nprint(Crema_df.Emotions.value_counts())\n\n\n# %% [code]\n#Savee Dataset\n\n# %% [code]\nsavee_directory_list = os.listdir(Savee)\n\nfile_emotion = []\nfile_path = []\n\nfor file in savee_directory_list:\n    file_path.append(Savee + file)\n    part = file.split('_')[1]\n    ele = part[:-6]\n    if ele=='a':\n        file_emotion.append('angry')\n    elif ele=='d':\n        file_emotion.append('disgust')\n    elif ele=='f':\n        file_emotion.append('fear')\n    elif ele=='h':\n        file_emotion.append('happy')\n    elif ele=='n':\n        file_emotion.append('neutral')\n    elif ele=='sa':\n        file_emotion.append('sad')\n    else:\n        file_emotion.append('surprise')\n        \n# dataframe for emotion of files\nemotion_df = pd.DataFrame(file_emotion, columns=['Emotions'])\n\n# dataframe for path of files.\npath_df = pd.DataFrame(file_path, columns=['Path'])\nSavee_df = pd.concat([emotion_df, path_df], axis=1)\nSavee_df.head()\nprint(Savee_df.Emotions.value_counts())\n\n\n# %% [markdown]\n# **Integration**\n\n# %% [code]\n# creating Dataframe using all the 4 dataframes we created so far.\ndata_path = pd.concat([ravdess_df, Crema_df, Tess_df, Savee_df], axis = 0)\ndata_path.to_csv(\"data_path.csv\",index=False)\ndata_path.head()\n\n# %% [code]\nprint(data_path.Emotions.value_counts())\n\n\n# %% [code] {\"scrolled\":true}\nimport matplotlib.pyplot as plt\nimport seaborn as sns\n\nplt.title('Count of Emotions', size=16)\nsns.countplot(data_path.Emotions)\nplt.ylabel('Count', size=12)\nplt.xlabel('Emotions', size=12)\nsns.despine(top=True, right=True, left=False, bottom=False)\nplt.show()\n\n# %% [code]\ndata,sr = librosa.load(file_path[0])\nsr\n\n# %% [code]\nipd.Audio(data,rate=sr)\n\n# %% [code]\n# CREATE LOG MEL SPECTROGRAM\nplt.figure(figsize=(10, 5))\nspectrogram = librosa.feature.melspectrogram(y=data, sr=sr, n_mels=128,fmax=8000) \nlog_spectrogram = librosa.power_to_db(spectrogram)\nlibrosa.display.specshow(log_spectrogram, y_axis='mel', sr=sr, x_axis='time');\nplt.title('Mel Spectrogram ')\nplt.colorbar(format='%+2.0f dB')\n\n# %% [code]\nmfcc = librosa.feature.mfcc(y=data, sr=sr, n_mfcc=30)\n\n\n# MFCC\nplt.figure(figsize=(16, 10))\nplt.subplot(3,1,1)\nlibrosa.display.specshow(mfcc, x_axis='time')\nplt.ylabel('MFCC')\nplt.colorbar()\n\nipd.Audio(data,rate=sr)\n\n# %% [markdown]\n# # Data augmentation\n\n# %% [code]\n# NOISE\ndef noise(data):\n    noise_amp = 0.035*np.random.uniform()*np.amax(data)\n    data = data + noise_amp*np.random.normal(size=data.shape[0])\n    return data\n\n# STRETCH\ndef stretch(data, rate=0.8):\n    return librosa.effects.time_stretch(data, rate)\n# SHIFT\ndef shift(data):\n    shift_range = int(np.random.uniform(low=-5, high = 5)*1000)\n    return np.roll(data, shift_range)\n# PITCH\ndef pitch(data, sampling_rate, pitch_factor=0.7):\n    return librosa.effects.pitch_shift(data, sampling_rate, pitch_factor)\n\n# %% [code]\n# NORMAL AUDIO\n\n\nimport librosa.display\nplt.figure(figsize=(12, 5))\nlibrosa.display.waveshow(y=data, sr=sr)\nipd.Audio(data,rate=sr)\n\n# %% [code]\n# AUDIO WITH NOISE\nx = noise(data)\nplt.figure(figsize=(12,5))\nlibrosa.display.waveshow(y=x, sr=sr)\nipd.Audio(x, rate=sr)\n\n# %% [code]\n# STRETCHED AUDIO\nx = stretch(data)\nplt.figure(figsize=(12, 5))\nlibrosa.display.waveshow(y=x, sr=sr)\nipd.Audio(x, rate=sr)\n\n# %% [code]\n# SHIFTED AUDIO\nx = shift(data)\nplt.figure(figsize=(12,5))\nlibrosa.display.waveshow(y=x, sr=sr)\nipd.Audio(x, rate=sr)\n\n# %% [code]\n# AUDIO WITH PITCH\nx = pitch(data, sr)\nplt.figure(figsize=(12, 5))\nlibrosa.display.waveshow(y=x, sr=sr)\nipd.Audio(x, rate=sr)\n\n# %% [markdown]\n# # Feature extraction\n\n# %% [code]\ndef zcr(data,frame_length,hop_length):\n    zcr=librosa.feature.zero_crossing_rate(data,frame_length=frame_length,hop_length=hop_length)\n    return np.squeeze(zcr)\ndef rmse(data,frame_length=2048,hop_length=512):\n    rmse=librosa.feature.rms(data,frame_length=frame_length,hop_length=hop_length)\n    return np.squeeze(rmse)\ndef mfcc(data,sr,frame_length=2048,hop_length=512,flatten:bool=True):\n    mfcc=librosa.feature.mfcc(data,sr=sr)\n    return np.squeeze(mfcc.T)if not flatten else np.ravel(mfcc.T)\n\ndef extract_features(data,sr=22050,frame_length=2048,hop_length=512):\n    result=np.array([])\n    \n    result=np.hstack((result,\n                      zcr(data,frame_length,hop_length),\n                      rmse(data,frame_length,hop_length),\n                      mfcc(data,sr,frame_length,hop_length)\n                     ))\n    return result\n\ndef get_features(path,duration=2.5, offset=0.6):\n    data,sr=librosa.load(path,duration=duration,offset=offset)\n    aud=extract_features(data)\n    audio=np.array(aud)\n    \n    noised_audio=noise(data)\n    aud2=extract_features(noised_audio)\n    audio=np.vstack((audio,aud2))\n    \n    pitched_audio=pitch(data,sr)\n    aud3=extract_features(pitched_audio)\n    audio=np.vstack((audio,aud3))\n    \n    pitched_audio1=pitch(data,sr)\n    pitched_noised_audio=noise(pitched_audio1)\n    aud4=extract_features(pitched_noised_audio)\n    audio=np.vstack((audio,aud4))\n    \n    return audio\n\n\n# %% [code]\nimport multiprocessing as mp\nprint(\"Number of processors: \", mp.cpu_count())\n\n# %% [markdown]\n# # Get features\n\n# %% [code]\nimport timeit\nfrom tqdm import tqdm\nstart = timeit.default_timer()\nX,Y=[],[]\nfor path,emotion,index in tqdm (zip(data_path.Path,data_path.Emotions,range(data_path.Path.shape[0]))):\n    features=get_features(path)\n    if index%500==0:\n        print(f'{index} audio has been processed')\n    for i in features:\n        X.append(i)\n        Y.append(emotion)\nprint('Done')\nstop = timeit.default_timer()\n\nprint('Time: ', stop - start)         \n\n# %% [code]\nlen(X), len(Y), data_path.Path.shape\n\n\n# %% [markdown]\n# # Saving features\n\n# %% [code]\nEmotions = pd.DataFrame(X)\nEmotions['Emotions'] = Y\nEmotions.to_csv('emotion.csv', index=False)\nEmotions.head()\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:12:39.844437Z\",\"iopub.execute_input\":\"2023-07-01T14:12:39.845764Z\",\"iopub.status.idle\":\"2023-07-01T14:13:11.793086Z\",\"shell.execute_reply.started\":\"2023-07-01T14:12:39.845719Z\",\"shell.execute_reply\":\"2023-07-01T14:13:11.791894Z\"}}\nEmotions = pd.read_csv('./emotion.csv')\nEmotions.head()\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:13:20.478364Z\",\"iopub.execute_input\":\"2023-07-01T14:13:20.478782Z\",\"iopub.status.idle\":\"2023-07-01T14:13:20.591283Z\",\"shell.execute_reply.started\":\"2023-07-01T14:13:20.478748Z\",\"shell.execute_reply\":\"2023-07-01T14:13:20.59011Z\"}}\nprint(Emotions.isna().any())\n\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:14:12.849004Z\",\"iopub.execute_input\":\"2023-07-01T14:14:12.849527Z\",\"iopub.status.idle\":\"2023-07-01T14:14:13.644166Z\",\"shell.execute_reply.started\":\"2023-07-01T14:14:12.849485Z\",\"shell.execute_reply\":\"2023-07-01T14:14:13.643133Z\"}}\nEmotions=Emotions.fillna(0)\nprint(Emotions.isna().any())\nEmotions.shape\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:15:14.791887Z\",\"iopub.execute_input\":\"2023-07-01T14:15:14.792542Z\",\"iopub.status.idle\":\"2023-07-01T14:15:15.065121Z\",\"shell.execute_reply.started\":\"2023-07-01T14:15:14.792504Z\",\"shell.execute_reply\":\"2023-07-01T14:15:15.06103Z\"}}\nnp.sum(Emotions.isna())\n\n# %% [markdown]\n# # Data preparation\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:15:24.797611Z\",\"iopub.execute_input\":\"2023-07-01T14:15:24.798163Z\",\"iopub.status.idle\":\"2023-07-01T14:15:25.07167Z\",\"shell.execute_reply.started\":\"2023-07-01T14:15:24.798128Z\",\"shell.execute_reply\":\"2023-07-01T14:15:25.07014Z\"}}\n#taking all rows and all cols without last col for X which include features\n#taking last col for Y, which include the emotions\n\n\nX = Emotions.iloc[: ,:-1].values\nY = Emotions['Emotions'].values\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:15:27.982903Z\",\"iopub.execute_input\":\"2023-07-01T14:15:27.983302Z\",\"iopub.status.idle\":\"2023-07-01T14:15:28.010889Z\",\"shell.execute_reply.started\":\"2023-07-01T14:15:27.983269Z\",\"shell.execute_reply\":\"2023-07-01T14:15:28.009953Z\"}}\n# As this is a multiclass classification problem onehotencoding our Y\nfrom sklearn.preprocessing import StandardScaler, OneHotEncoder\nencoder = OneHotEncoder()\nY = encoder.fit_transform(np.array(Y).reshape(-1,1)).toarray()\n\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:15:31.349185Z\",\"iopub.execute_input\":\"2023-07-01T14:15:31.349601Z\",\"iopub.status.idle\":\"2023-07-01T14:15:31.360147Z\",\"shell.execute_reply.started\":\"2023-07-01T14:15:31.349544Z\",\"shell.execute_reply\":\"2023-07-01T14:15:31.359008Z\"}}\nprint(Y.shape)\nX.shape\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:15:38.349555Z\",\"iopub.execute_input\":\"2023-07-01T14:15:38.350324Z\",\"iopub.status.idle\":\"2023-07-01T14:15:39.851001Z\",\"shell.execute_reply.started\":\"2023-07-01T14:15:38.350288Z\",\"shell.execute_reply\":\"2023-07-01T14:15:39.849048Z\"}}\nfrom sklearn.model_selection import train_test_split\n\nx_train, x_test, y_train, y_test = train_test_split(X, Y, random_state=42,test_size=0.2, shuffle=True)\nx_train.shape, y_train.shape, x_test.shape, y_test.shape\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:15:50.558408Z\",\"iopub.execute_input\":\"2023-07-01T14:15:50.559638Z\",\"iopub.status.idle\":\"2023-07-01T14:15:50.566028Z\",\"shell.execute_reply.started\":\"2023-07-01T14:15:50.559554Z\",\"shell.execute_reply\":\"2023-07-01T14:15:50.56481Z\"}}\n#reshape for lstm\nX_train = x_train.reshape(x_train.shape[0] , x_train.shape[1] , 1)\nX_test = x_test.reshape(x_test.shape[0] , x_test.shape[1] , 1)\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:15:54.922397Z\",\"iopub.execute_input\":\"2023-07-01T14:15:54.922899Z\",\"iopub.status.idle\":\"2023-07-01T14:15:56.412083Z\",\"shell.execute_reply.started\":\"2023-07-01T14:15:54.922861Z\",\"shell.execute_reply\":\"2023-07-01T14:15:56.410934Z\"}}\n# scaling our data with sklearn's Standard scaler\nscaler = StandardScaler()\nx_train = scaler.fit_transform(x_train)\nx_test = scaler.transform(x_test)\nx_train.shape, y_train.shape, x_test.shape, y_test.shape\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:15:58.194656Z\",\"iopub.execute_input\":\"2023-07-01T14:15:58.195057Z\",\"iopub.status.idle\":\"2023-07-01T14:15:58.203537Z\",\"shell.execute_reply.started\":\"2023-07-01T14:15:58.195024Z\",\"shell.execute_reply\":\"2023-07-01T14:15:58.202326Z\"}}\nimport keras\nfrom keras.preprocessing import sequence\nfrom keras.models import Sequential\nfrom keras.layers import Dense, Embedding\nfrom keras.layers import LSTM,BatchNormalization , GRU\nfrom keras.preprocessing.text import Tokenizer\nfrom keras.preprocessing.sequence import pad_sequences\nfrom tensorflow.keras.utils import to_categorical\nfrom keras.layers import Input, Flatten, Dropout, Activation\nfrom keras.layers import Conv1D, MaxPooling1D, AveragePooling1D\nfrom keras.models import Model\nfrom keras.callbacks import ModelCheckpoint\nfrom tensorflow.keras.optimizers import SGD\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T15:29:27.391353Z\",\"iopub.execute_input\":\"2023-07-01T15:29:27.39179Z\",\"iopub.status.idle\":\"2023-07-01T15:29:27.397433Z\",\"shell.execute_reply.started\":\"2023-07-01T15:29:27.391755Z\",\"shell.execute_reply\":\"2023-07-01T15:29:27.396158Z\"}}\nfrom keras.callbacks import ModelCheckpoint, EarlyStopping,ReduceLROnPlateau\nmodel_checkpoint = ModelCheckpoint('best_model1_weights.h5', monitor='val_accuracy', save_best_only=True)\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T15:29:29.544486Z\",\"iopub.execute_input\":\"2023-07-01T15:29:29.545573Z\",\"iopub.status.idle\":\"2023-07-01T15:29:29.551708Z\",\"shell.execute_reply.started\":\"2023-07-01T15:29:29.545519Z\",\"shell.execute_reply\":\"2023-07-01T15:29:29.550469Z\"}}\n\nearly_stop=EarlyStopping(monitor='val_acc',mode='auto',patience=5,restore_best_weights=True)\nlr_reduction=ReduceLROnPlateau(monitor='val_acc',patience=3,verbose=1,factor=0.5,min_lr=0.00001)\n\n# %% [markdown]\n# # CNN model\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T14:16:39.773793Z\",\"iopub.execute_input\":\"2023-07-01T14:16:39.774859Z\",\"iopub.status.idle\":\"2023-07-01T14:16:39.783285Z\",\"shell.execute_reply.started\":\"2023-07-01T14:16:39.77481Z\",\"shell.execute_reply\":\"2023-07-01T14:16:39.782276Z\"}}\n#Reshape for CNN_LSTM MODEL\n\nx_traincnn =np.expand_dims(x_train, axis=2)\nx_testcnn= np.expand_dims(x_test, axis=2)\nx_traincnn.shape, y_train.shape, x_testcnn.shape, y_test.shape\n#x_testcnn[0]\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T15:32:14.956885Z\",\"iopub.execute_input\":\"2023-07-01T15:32:14.957331Z\",\"iopub.status.idle\":\"2023-07-01T15:32:15.16189Z\",\"shell.execute_reply.started\":\"2023-07-01T15:32:14.957295Z\",\"shell.execute_reply\":\"2023-07-01T15:32:15.160802Z\"}}\nimport tensorflow.keras.layers as L\n\nmodel = tf.keras.Sequential([\n    L.Conv1D(512,kernel_size=5, strides=1,padding='same', activation='relu',input_shape=(X_train.shape[1],1)),\n    L.BatchNormalization(),\n    L.MaxPool1D(pool_size=5,strides=2,padding='same'),\n    \n    L.Conv1D(512,kernel_size=5,strides=1,padding='same',activation='relu'),\n    L.BatchNormalization(),\n    L.MaxPool1D(pool_size=5,strides=2,padding='same'),\n    Dropout(0.2),  # Add dropout layer after the second max pooling layer\n    \n    L.Conv1D(256,kernel_size=5,strides=1,padding='same',activation='relu'),\n    L.BatchNormalization(),\n    L.MaxPool1D(pool_size=5,strides=2,padding='same'),\n    \n    L.Conv1D(256,kernel_size=3,strides=1,padding='same',activation='relu'),\n    L.BatchNormalization(),\n    L.MaxPool1D(pool_size=5,strides=2,padding='same'),\n    Dropout(0.2),  # Add dropout layer after the fourth max pooling layer\n    \n    L.Conv1D(128,kernel_size=3,strides=1,padding='same',activation='relu'),\n    L.BatchNormalization(),\n    L.MaxPool1D(pool_size=3,strides=2,padding='same'),\n    Dropout(0.2),  # Add dropout layer after the fifth max pooling layer\n    \n    L.Flatten(),\n    L.Dense(512,activation='relu'),\n    L.BatchNormalization(),\n    L.Dense(7,activation='softmax')\n])\nmodel.compile(optimizer='adam',loss='categorical_crossentropy',metrics='accuracy')\nmodel.summary()\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T15:32:35.07213Z\",\"iopub.execute_input\":\"2023-07-01T15:32:35.072523Z\",\"iopub.status.idle\":\"2023-07-01T17:27:18.409989Z\",\"shell.execute_reply.started\":\"2023-07-01T15:32:35.072489Z\",\"shell.execute_reply\":\"2023-07-01T17:27:18.408827Z\"}}\nhistory=model.fit(x_traincnn, y_train, epochs=50, validation_data=(x_testcnn, y_test), batch_size=64,callbacks=[early_stop,lr_reduction,model_checkpoint])\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T17:28:04.121872Z\",\"iopub.execute_input\":\"2023-07-01T17:28:04.122599Z\",\"iopub.status.idle\":\"2023-07-01T17:28:12.073531Z\",\"shell.execute_reply.started\":\"2023-07-01T17:28:04.122537Z\",\"shell.execute_reply\":\"2023-07-01T17:28:12.072495Z\"}}\nprint(\"Accuracy of our model on test data : \" , model.evaluate(x_testcnn,y_test)[1]*100 , \"%\")\n\nepochs = [i for i in range(50)]\nfig , ax = plt.subplots(1,2)\ntrain_acc = history.history['accuracy']\ntrain_loss = history.history['loss']\ntest_acc = history.history['val_accuracy']\ntest_loss = history.history['val_loss']\n\nfig.set_size_inches(20,6)\nax[0].plot(epochs , train_loss , label = 'Training Loss')\nax[0].plot(epochs , test_loss , label = 'Testing Loss')\nax[0].set_title('Training & Testing Loss')\nax[0].legend()\nax[0].set_xlabel(\"Epochs\")\n\nax[1].plot(epochs , train_acc , label = 'Training Accuracy')\nax[1].plot(epochs , test_acc , label = 'Testing Accuracy')\nax[1].set_title('Training & Testing Accuracy')\nax[1].legend()\nax[1].set_xlabel(\"Epochs\")\nplt.show()\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T17:30:51.042829Z\",\"iopub.execute_input\":\"2023-07-01T17:30:51.043307Z\",\"iopub.status.idle\":\"2023-07-01T17:30:57.844806Z\",\"shell.execute_reply.started\":\"2023-07-01T17:30:51.043272Z\",\"shell.execute_reply\":\"2023-07-01T17:30:57.843606Z\"}}\n# predicting on test data.\npred_test0 = model.predict(x_testcnn)\ny_pred0 = encoder.inverse_transform(pred_test0)\ny_test0 = encoder.inverse_transform(y_test)\n\n# Check for random predictions\ndf0 = pd.DataFrame(columns=['Predicted Labels', 'Actual Labels'])\ndf0['Predicted Labels'] = y_pred0.flatten()\ndf0['Actual Labels'] = y_test0.flatten()\n\ndf0.head(10)\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T17:31:10.1825Z\",\"iopub.execute_input\":\"2023-07-01T17:31:10.18291Z\",\"iopub.status.idle\":\"2023-07-01T17:31:10.198159Z\",\"shell.execute_reply.started\":\"2023-07-01T17:31:10.182878Z\",\"shell.execute_reply\":\"2023-07-01T17:31:10.1971Z\"}}\ndf0\n\n# %% [markdown]\n# # Evalutation\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T17:31:55.291417Z\",\"iopub.execute_input\":\"2023-07-01T17:31:55.292233Z\",\"iopub.status.idle\":\"2023-07-01T17:31:56.273819Z\",\"shell.execute_reply.started\":\"2023-07-01T17:31:55.292193Z\",\"shell.execute_reply\":\"2023-07-01T17:31:56.272713Z\"}}\nfrom sklearn.metrics import confusion_matrix,classification_report\ncm = confusion_matrix(y_test0, y_pred0)\nplt.figure(figsize = (12, 10))\ncm = pd.DataFrame(cm , index = [i for i in encoder.categories_] , columns = [i for i in encoder.categories_])\n#cm = cm.astype('float') / cm.sum(axis=1)[:, np.newaxis]\nsns.heatmap(cm, linecolor='white', cmap='Blues', linewidth=1, annot=True, fmt='.2f')\nplt.title('Confusion Matrix', size=20)\nplt.xlabel('Predicted Labels', size=14)\nplt.ylabel('Actual Labels', size=14)\nplt.show()\nprint(classification_report(y_test0, y_pred0))\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T17:33:01.344471Z\",\"iopub.execute_input\":\"2023-07-01T17:33:01.345546Z\",\"iopub.status.idle\":\"2023-07-01T17:33:01.428663Z\",\"shell.execute_reply.started\":\"2023-07-01T17:33:01.345505Z\",\"shell.execute_reply\":\"2023-07-01T17:33:01.427516Z\"}}\n# MLP for Pima Indians Dataset Serialize to JSON and HDF5\nfrom tensorflow.keras.models import Sequential, model_from_json\nmodel_json = model.to_json()\nwith open(\"CNN_model.json\", \"w\") as json_file:\n    json_file.write(model_json)\n# serialize weights to HDF5\nmodel.save_weights(\"CNN_model_weights.h5\")\nprint(\"Saved model to disk\") \n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T17:35:04.565263Z\",\"iopub.execute_input\":\"2023-07-01T17:35:04.565702Z\",\"iopub.status.idle\":\"2023-07-01T17:35:04.81046Z\",\"shell.execute_reply.started\":\"2023-07-01T17:35:04.565666Z\",\"shell.execute_reply\":\"2023-07-01T17:35:04.809402Z\"}}\nfrom tensorflow.keras.models import Sequential, model_from_json\njson_file = open('/kaggle/working/CNN_model.json', 'r')\nloaded_model_json = json_file.read()\njson_file.close()\nloaded_model = model_from_json(loaded_model_json)\n# load weights into new model\nloaded_model.load_weights(\"/kaggle/working/best_model1_weights.h5\")\nprint(\"Loaded model from disk\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T17:35:07.554719Z\",\"iopub.execute_input\":\"2023-07-01T17:35:07.555111Z\",\"iopub.status.idle\":\"2023-07-01T17:35:18.491122Z\",\"shell.execute_reply.started\":\"2023-07-01T17:35:07.555077Z\",\"shell.execute_reply\":\"2023-07-01T17:35:18.489805Z\"}}\nloaded_model.compile(optimizer='adam', loss='categorical_crossentropy', metrics=['accuracy'])\nscore = loaded_model.evaluate(x_testcnn,y_test)\nprint(\"%s: %.2f%%\" % (loaded_model.metrics_names[1], score[1]*100))\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T17:36:13.510622Z\",\"iopub.execute_input\":\"2023-07-01T17:36:13.511327Z\",\"iopub.status.idle\":\"2023-07-01T17:36:13.521214Z\",\"shell.execute_reply.started\":\"2023-07-01T17:36:13.511288Z\",\"shell.execute_reply\":\"2023-07-01T17:36:13.52008Z\"}}\nimport pickle\n\n# Saving scaler\nwith open('scaler2.pickle', 'wb') as f:\n    pickle.dump(scaler, f)\n\n# Loading scaler\nwith open('scaler2.pickle', 'rb') as f:\n    scaler2 = pickle.load(f)\n\n# Saving encoder\nwith open('encoder2.pickle', 'wb') as f:\n    pickle.dump(encoder, f)\n\n# Loading encoder\nwith open('encoder2.pickle', 'rb') as f:\n    encoder2 = pickle.load(f)\n\n    \nprint(\"Done\")    \n\n# %% [markdown]\n# # Test script\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2024-09-26T20:17:37.664333Z\",\"iopub.execute_input\":\"2024-09-26T20:17:37.664767Z\",\"iopub.status.idle\":\"2024-09-26T20:17:44.534340Z\",\"shell.execute_reply.started\":\"2024-09-26T20:17:37.664684Z\",\"shell.execute_reply\":\"2024-09-26T20:17:44.532656Z\"}}\nfrom tensorflow.keras.models import Sequential, model_from_json\njson_file = open('/kaggle/working/CNN_model.json', 'r')\nloaded_model_json = json_file.read()\njson_file.close()\nloaded_model = model_from_json(loaded_model_json)\n# load weights into new model\nloaded_model.load_weights(\"/kaggle/working/best_model1_weights.h5\")\nprint(\"Loaded model from disk\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T17:39:16.28933Z\",\"iopub.execute_input\":\"2023-07-01T17:39:16.289749Z\",\"iopub.status.idle\":\"2023-07-01T17:39:16.297504Z\",\"shell.execute_reply.started\":\"2023-07-01T17:39:16.289715Z\",\"shell.execute_reply\":\"2023-07-01T17:39:16.296484Z\"}}\nimport pickle\n\nwith open('/kaggle/working/scaler2.pickle', 'rb') as f:\n    scaler2 = pickle.load(f)\n    \nwith open('/kaggle/working/encoder2.pickle', 'rb') as f:\n    encoder2 = pickle.load(f)\n\n    \nprint(\"Done\")    \n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T17:39:19.313258Z\",\"iopub.execute_input\":\"2023-07-01T17:39:19.313678Z\",\"iopub.status.idle\":\"2023-07-01T17:39:19.318718Z\",\"shell.execute_reply.started\":\"2023-07-01T17:39:19.313644Z\",\"shell.execute_reply\":\"2023-07-01T17:39:19.317546Z\"}}\nimport librosa\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T18:32:09.835495Z\",\"iopub.execute_input\":\"2023-07-01T18:32:09.835927Z\",\"iopub.status.idle\":\"2023-07-01T18:32:09.849153Z\",\"shell.execute_reply.started\":\"2023-07-01T18:32:09.835893Z\",\"shell.execute_reply\":\"2023-07-01T18:32:09.848116Z\"}}\ndef zcr(data,frame_length,hop_length):\n    zcr=librosa.feature.zero_crossing_rate(data,frame_length=frame_length,hop_length=hop_length)\n    return np.squeeze(zcr)\ndef rmse(data,frame_length=2048,hop_length=512):\n    rmse=librosa.feature.rms(data,frame_length=frame_length,hop_length=hop_length)\n    return np.squeeze(rmse)\ndef mfcc(data,sr,frame_length=2048,hop_length=512,flatten:bool=True):\n    mfcc=librosa.feature.mfcc(data,sr=sr)\n    return np.squeeze(mfcc.T)if not flatten else np.ravel(mfcc.T)\n\ndef extract_features(data,sr=22050,frame_length=2048,hop_length=512):\n    result=np.array([])\n    \n    result=np.hstack((result,\n                      zcr(data,frame_length,hop_length),\n                      rmse(data,frame_length,hop_length),\n                      mfcc(data,sr,frame_length,hop_length)\n                     ))\n    return result\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T18:32:12.238453Z\",\"iopub.execute_input\":\"2023-07-01T18:32:12.239326Z\",\"iopub.status.idle\":\"2023-07-01T18:32:12.246339Z\",\"shell.execute_reply.started\":\"2023-07-01T18:32:12.239288Z\",\"shell.execute_reply\":\"2023-07-01T18:32:12.245151Z\"}}\ndef get_predict_feat(path):\n    d, s_rate= librosa.load(path, duration=2.5, offset=0.6)\n    res=extract_features(d)\n    result=np.array(res)\n    result=np.reshape(result,newshape=(1,2376))\n    i_result = scaler2.transform(result)\n    final_result=np.expand_dims(i_result, axis=2)\n    \n    return final_result\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T18:32:13.946415Z\",\"iopub.execute_input\":\"2023-07-01T18:32:13.947186Z\",\"iopub.status.idle\":\"2023-07-01T18:32:14.048298Z\",\"shell.execute_reply.started\":\"2023-07-01T18:32:13.947146Z\",\"shell.execute_reply\":\"2023-07-01T18:32:14.047226Z\"}}\nres=get_predict_feat(\"/kaggle/input/ravdess-emotional-speech-audio/Actor_01/03-01-07-01-01-01-01.wav\")\nprint(res.shape)\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T18:32:16.801094Z\",\"iopub.execute_input\":\"2023-07-01T18:32:16.801488Z\",\"iopub.status.idle\":\"2023-07-01T18:32:16.808781Z\",\"shell.execute_reply.started\":\"2023-07-01T18:32:16.801453Z\",\"shell.execute_reply\":\"2023-07-01T18:32:16.807611Z\"}}\nemotions1={1:'Neutral', 2:'Calm', 3:'Happy', 4:'Sad', 5:'Angry', 6:'Fear', 7:'Disgust',8:'Surprise'}\ndef prediction(path1):\n    res=get_predict_feat(path1)\n    predictions=loaded_model.predict(res)\n    y_pred = encoder2.inverse_transform(predictions)\n    print(y_pred[0][0])    \n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2023-07-01T18:32:18.648136Z\",\"iopub.execute_input\":\"2023-07-01T18:32:18.648537Z\",\"iopub.status.idle\":\"2023-07-01T18:32:18.830837Z\",\"shell.execute_reply.started\":\"2023-07-01T18:32:18.648504Z\",\"shell.execute_reply\":\"2023-07-01T18:32:18.829298Z\"}}\nprediction(\"\")","metadata":{"_uuid":"59cbba69-51c1-49bf-9305-92f675fa1150","_cell_guid":"62954761-f0f8-4897-afeb-26d320ed1b81","collapsed":false,"jupyter":{"outputs_hidden":false},"trusted":true},"execution_count":null,"outputs":[]}]}